export function getPhotosForZone(stationCode: string, zoneNumber: number): DrivePhotoFile[] {
  const key = `${stationCode}_Z${zoneNumber}`;
  const entry = DRIVE_PHOTOS_MANIFEST[key];
  if (entry && 'files' in entry && Array.isArray(entry.files) && entry.files.length > 0) {
    return entry.files;
  }
  return [];
}

export function getPhotosByFolderId(folderId: string): DrivePhotoFile[] {
  const direct = DRIVE_PHOTOS_MANIFEST[folderId];
  if (direct && Array.isArray(direct)) {
    return direct;
  }
  for (const key of Object.keys(DRIVE_PHOTOS_MANIFEST)) {
    const entry = DRIVE_PHOTOS_MANIFEST[key];
    if (entry && 'folderId' in entry && entry.folderId === folderId && entry.files) {
      return entry.files;
    }
  }
  return [];
}
